function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function call(path,options={}){const response=await fetch(origin()+path,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.status===204?{}:response.json()}
async function initialize(id){const encoded=encodeURIComponent(id);const [project,dataRecipe,validation]=await Promise.all([call('/api/strategy/projects/'+encoded),call('/api/data-sync/recipes/'+encoded),call('/api/validation/projects/'+encoded)]);delete project.draft_source;delete project.strategy_source;if(dataRecipe.draft)delete dataRecipe.draft.source;delete validation.source;return{project,data_recipe:dataRecipe,validation}}
async function run(input){const op=String(input.operation||''),id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');if(op==='delete'){if(input.confirm_delete!==true)throw new Error('Deleting a research project requires explicit confirmation');const previous=await call('/api/strategy/projects/'+encodeURIComponent(id));await call('/api/strategy/projects/'+encodeURIComponent(id)+'?confirm_delete=true',{method:'DELETE'});return{deleted:true,project_id:id,previous_source_sha256:previous.draft_source_sha256}}if(input.confirm_write!==true)throw new Error('Project mutation requires confirm_write=true');if(op==='create'||op==='clone'){if(input.confirm_python_execution!==true)throw new Error('Project creation validates trusted local Python and requires confirmation');if(!input.name)throw new Error('name is required');const source=op==='create'?'sdk-v1-default':String(input.source_project_id||'').trim();if(!source)throw new Error('source_project_id is required for clone');await call('/api/strategy/projects/'+encodeURIComponent(source)+'/clone',{method:'POST',body:JSON.stringify({target_id:id,name:String(input.name),confirm_save:true,confirm_python_execution:true})});return initialize(id)}if(op==='update_metadata'){const current=await call('/api/strategy/projects/'+encodeURIComponent(id));const project=await call('/api/strategy/projects/'+encodeURIComponent(id)+'/metadata',{method:'PUT',body:JSON.stringify({name:input.name||current.name,description:input.description===undefined?current.description:String(input.description),profile:'runtime',settings:input.settings||current.settings,confirm_write:true})});delete project.draft_source;delete project.strategy_source;return{project}}throw new Error('unsupported project operation')}
